-- Schema only: customer rows are deliberately excluded from public source.
begin;
-- G&S Counter — import from Notion. Generated by migrate/build.py; don't hand-edit.
-- Safe to run more than once: customers match on name, history on date.
--
-- 65 customers from the Notion Customer Database
-- 84 days of takings from Steward Logs (2026-03-20 to 2026-10-16)

-- ---------------------------------------------------------------- customers
-- Seeds the counter's name lookup, so a regular's email is already there
-- when a steward starts typing and the receipt can go straight out.
create table if not exists public.customers (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  email       text,
  phone       text,
  note        text,
  from_notion boolean not null default false,
  shop_known  boolean not null default false,  -- had shop visits logged in Notion
  since       date,
  created_at  timestamptz not null default now()
);
create unique index if not exists customers_name_key on public.customers (lower(name));

-- ------------------------------------------------------------ daily history
-- Takings per day before the counter existed. One number per day, which is
-- all Notion recorded — no items, no payment methods, no customer attached.
-- Deliberately NOT in `sales`: those rows are real transactions with line
-- items, and mixing a bare total in would make the sales book untrue.
--
-- studio is null throughout: the Store field was never filled in Notion, so
-- which site took the money is genuinely unknown. Don't guess it later.
create table if not exists public.daily_history (
  day        date primary key,
  studio     text,
  total      numeric(10,2) not null,
  day_type   text,
  source     text not null default 'notion-steward-logs',
  created_at timestamptz not null default now()
);


-- Customer contacts require steward access. Public launch access is a separate, expiring policy.
alter table public.customers enable row level security;
alter table public.daily_history enable row level security;
grant select, insert, update, delete on public.customers to anon, authenticated;
grant select on public.daily_history to anon, authenticated;
do $$
declare t text;
begin
  foreach t in array array['customers','daily_history'] loop
    execute format('drop policy if exists %I_open_read on public.%I', t, t);
    execute format('drop policy if exists %I_open_write on public.%I', t, t);
    execute format('drop policy if exists %I_read on public.%I', t, t);
    execute format('create policy %I_read on public.%I for select to authenticated using (public.is_steward())', t, t);
  end loop;
end $$;
drop policy if exists customers_write on public.customers;
create policy customers_write on public.customers for all to authenticated using (public.is_steward()) with check(public.is_steward());
drop policy if exists daily_history_launch_read on public.daily_history;
create policy daily_history_launch_read on public.daily_history for select to anon using (CURRENT_TIMESTAMP < TIMESTAMPTZ '2026-10-20 13:00:00+00');
do $$
begin
  begin execute 'alter publication supabase_realtime add table public.customers';
  exception when duplicate_object then null; end;
end $$;

commit;
